import datetime
import re
import time

from taf.sbts.oam.coam.admin import admin
from taf.rfrl.procedures.resources.python.connections import get_default_admin_connection_alias
from taf.rfrl.procedures.resources.python.logger import log_step, log_result, log_input_and_output

from taf.rfrl.procedures.resources.python.counters.core.exceptions import (
    CounterNotFound,
    NoCountersReported,
    DifferenceBetweenCountersExceedsDesiredRange,
)


class Core(object):

    def __init__(self):
        self.api = admin()
        self.counters = None
        self.last_read_time = None
        self.real_time_measurements = None

    @property
    def api_connection_alias(self):
        return get_default_admin_connection_alias()

    @log_input_and_output
    def get_counters(self):
        log_step("Getting read counters...")
        return self.counters

    @log_input_and_output
    def get_last_read_time(self):
        log_step("Getting last counters read time...")
        return self.last_read_time

    @log_input_and_output
    def get_real_time_measurements(self):
        """
        Updates value of real_time_measurements attribute
        with Real Time Measurements
        :return: updated real_time_measurements attribute
        """
        log_step("Getting real time measurements...")
        return self.real_time_measurements

    @log_input_and_output
    def get_counters_for_specific_object(self, object_name):
        try:
            log_step("Getting counters of {0}...".format(object_name))
            res = self.counters[object_name]

        except KeyError:
            raise KeyError("There is no {0} object in counters data!".format(object_name))

        return res

    @log_input_and_output
    def load_counters(self, timeout=180, counter_ids=None, wrap=False):
        """
        Loads counters via api

        :param counter_ids: List of Counter IDs or str (split by comma) to be loaded,
                            e.g. ["M40002C0", "M40002C1"] or "M40002C0,M40002C1". If None, all counters will be loaded
        :type counter_ids: list| str | None
        :param wrap: When set to True returns a parsed and concise list with counter info.
                     e.g. before wrap
                     {'MRBTS-50173': {'EQM-1': {'APEQM-1': {'RMOD-3': {'SBTS_RFM_Energy_Monitoring': {'M40003C0': {'1758635340': 52813}}}}}}}
                     after wrap
                     {'RMOD-3/SBTS_RFM_Energy_Monitoring/M40003C0: {'1758635340': 52813}}
        :type wrap: bool
        :param timeout: timeout for operation in seconds, default is 180s
        :type timeout: int
        """
        if isinstance(counter_ids, list):
            counter_ids = ','.join(counter_ids)

        log_step(f"Getting {'all' if not counter_ids else counter_ids} BTS counters dictionary via API...")
        _counters = self.api.get_pm_counters(counter_ids=counter_ids, connection=self.api_connection_alias, wrap_nidd=wrap, timeout=timeout)
        self.counters = self._wrap_counters(_counters) if wrap else _counters['BTS']
        log_result(f"Counters loaded\n{self.counters}")

        self._update_last_read_time()

    @log_input_and_output
    def get_counter_by_id(self, counter_id, component_name=None):
        """
        Returns counter with provided id from counters data. If component_name is provided, it will return
        counter from specified component, if not it will return the first occurrence of provided counter ID.
        :param counter_id: ID of the counter, e.g. "M40002C0"
        :type counter_id: str
        :param component_name: name of the component that contains specific counter, e.g. "NRCELL-1"
        :type component_name: str
        :return: counter values with provided id, e.g.
                 {"NRCELL-1/NRUC/M40002C0": {"1653292560": 50129, "1753292560": 51129, "1953292560": 52129}}
        :rtype: dict
        :raises CounterNotFound: when counter with provided id is not found
        """
        log_step("Looking for {0} counter in whole counters data".format(counter_id))
        counters = self.counters
        if component_name:
            counters = self._get_nested_key(counter=component_name, counters=counters)

        found_counter = self._get_nested_key(counter=counter_id, counters=counters)

        if not found_counter:
            raise CounterNotFound("Couldn't find counter with provided id: '{0}'".format(counter_id))

        log_result("Counter found!")
        return found_counter

    @log_input_and_output
    def get_counters_from_specific_time_period(self, startpoint, endpoint, counter_id, all_counter_values):
        """
        Returns a dict of counters specified by counter_names list from a time period between
        startpoint and endpoint

        :param startpoint: starting timestamp for the verification i.e. '2022-10-23 18:15:15.030'
        :type startpoint: str
        :param endpoint: finishing timestamp for the verification i.e. '2022-10-23 18:47:15.159'
        :type endpoint: str
        :param counter_id: ID of the counter
        :type counter_id: str
        :param all_counter_values: dict with all counters read from BTS
                for example: {
                        "M40002C0": {"1653292560": 50129, "1753292560": 51129, "1953292560": 52129},
                        "M40002C1": {"1653292561": 51129, "1753292561": 52129, "1953292561": 53129},
                        "M40002C2": {"1653292562": 305306, "1753292562": 305306, "1953292562": 305306},
                    }
        :type all_counter_values: dict(str, dict(int, int))


        :return: dict of values from the specified time period for counter
        :rtype: dict(str, int)
        """
        startpoint = self._adjust_verification_startpoint(
            verification_startpoint=startpoint)

        startpoint_unix, endpoint_unix = self._convert_timestamp_to_unix(
            verification_startpoint=startpoint, verification_endpoint=endpoint
        )

        counters_from_timeperiod = {counter_id: self._get_values_of_counter_from_specific_time_period(
            counters_dict=all_counter_values,
            counter_name=counter_id,
            startpoint=startpoint_unix,
            endpoint=endpoint_unix
        )}

        return counters_from_timeperiod

    @log_input_and_output
    def compare_counters(self, counters_1, counters_2, lower_limit, upper_limit):
        """
        Compares values of counters from lists of dicts or dicts counters_1 and counters_2
        The difference between counter's values should be in range lower_limit - upper_limit.

        :param counters_1: list of dicts or dict with counters values
        :type counters_1: list(dict(str, float)) or dict(str, float)
        :param counters_2: list of dicts or dict with counters values
        :type counters_2: list(dict(str, float)) or dict(str, float)
        :param lower_limit: lower limit of desired difference between counters
        :type lower_limit: int
        :param upper_limit: upper limit of desired difference between counters
        :type upper_limit: int

        :raises DifferenceBetweenCountersExceedsDesiredRange: when the difference
        between counters is not between lower_limit and upper_limit.
        """
        if isinstance(counters_1, list) and isinstance(counters_2, list):
            counters_1 = self._convert_list_of_dicts_into_single_dict(list_of_dicts=counters_1)
            counters_2 = self._convert_list_of_dicts_into_single_dict(list_of_dicts=counters_2)

        difference_dict = self._get_difference_dict(counters_1=counters_1,
                                                    counters_2=counters_2)

        for counter, counters_difference in difference_dict.items():
            for difference in counters_difference:
                if difference < int(lower_limit) or difference > int(upper_limit):
                    raise DifferenceBetweenCountersExceedsDesiredRange(
                        'Difference between counter values for counter {0} '
                        'exceeds the given limit: {1} - {2}. Difference: {3}'.format(
                            counter, lower_limit, upper_limit, difference))

        log_result("Counters verification complete!")

    def _update_last_read_time(self):
        log_step("Update'ing last counters read time...")
        self.last_read_time = datetime.datetime.now()

    def _get_nested_key(self, counter, counters):
        return_dict = {}
        if isinstance(counters, dict):
            for key, value in counters.items():
                if counter == key or any(counter == e for e in key.split('/')):
                    return_dict[key] = value
                    continue
                return_dict.update(self._get_nested_key(counter, value))
        elif isinstance(counters, (list, tuple)):
            for value in counters:
                return_dict.update(self._get_nested_key(counter, value))

        return return_dict

    @staticmethod
    def _get_n_last_frames(counter, n=2):
        sorted_timestamps = sorted([int(timestamp) for timestamp in counter.keys()])
        return {timestamp: counter[str(timestamp)] for timestamp in sorted_timestamps[-int(n):]}

    @staticmethod
    def _get_values_of_counter_from_specific_time_period(
            counters_dict, counter_name, startpoint, endpoint
    ):
        """
        Given the counters_dict makes a list of all the measurements taken during
        the specified time period between startpoint and endpoint.

        :param counters_dict: dict with all counters
        :type counters_dict: dict(str, dict(str, int)
        :param counter_name: name of the counter that needs to be verified
        :type counter_name: str
        :param startpoint: starting timestamp for the verification in UNIX format
        :type startpoint: float
        :param endpoint: finishing timestamp for the verification in UNIX format
        :type endpoint: float

        :raises: NoCountersReported when no counters from specified time period were found

        :return: list with energy consumption counters from specific time period
        :rtype: list(float)
        """
        counters_list = []

        for counter, values_dict in counters_dict.items():
            for timestamp, counter_value in values_dict.items():
                if counter == counter_name:
                    if startpoint <= int(timestamp) <= endpoint:
                        counters_list.append(float(counter_value))
        if not counters_list:
            raise NoCountersReported(
                "No counters were reported during the given time period!"
            )

        return counters_list

    @staticmethod
    def _convert_timestamp_to_unix(verification_startpoint, verification_endpoint):
        verification_startpoint = datetime.datetime.strptime(
            verification_startpoint, "%Y-%m-%d %H:%M:%S.%f"
        )
        verification_startpoint_unix = time.mktime(verification_startpoint.timetuple())

        verification_endpoint = datetime.datetime.strptime(
            verification_endpoint, "%Y-%m-%d %H:%M:%S.%f"
        )
        verification_endpoint_unix = time.mktime(verification_endpoint.timetuple())

        return int(verification_startpoint_unix), int(verification_endpoint_unix)

    @log_input_and_output
    def _convert_list_of_dicts_into_single_dict(self, list_of_dicts):
        single_dict = {}
        for element in list_of_dicts:
            single_dict.update(element)

        return single_dict

    @log_input_and_output
    def _get_difference_dict(self, counters_1, counters_2):
        difference_dict = {}
        for counter in counters_1.keys():
            difference_list = []
            for value_1, value_2 in zip(counters_1[counter], counters_2[counter]):
                difference_list.append(value_1 - value_2)

            difference_dict[counter] = difference_list

        return difference_dict

    @staticmethod
    def _adjust_verification_startpoint(verification_startpoint):
        startpoint_second = verification_startpoint.split(":")[-1]
        if float(startpoint_second) > 0.0:
            return verification_startpoint.replace(startpoint_second, '00.00')

        return verification_startpoint

    def _wrap_counters(self, counters, parent_key="", path_deep=3):
        """
        Wrap counter info returned by load_counters(wrap=True)

        :param counters: counters dictionary returned by load_counters(wrap=True) e.g.
                        {'MRBTS-50173/EQM-1/APEQM-1/RMOD-1': {'SBTS_RFM_Energy_Monitoring': {'M40003C0': {'1758635340': 52813}}},
                         'MRBTS-50173/EQM-1/APEQM-1/RMOD-2': {'SBTS_RFM_Energy_Monitoring': {'M40003C0': {'1758635340': 62813}}}}
        :type counters: dict
        :param parent_key: used in recursion to build full path of the counter
        :type parent_key: str
        :param path_deep: how many last parts of the path to keep starting from the counter ID, default is 3
        :type path_deep: int
        :return: wrapped counters dictionary e.g. for path_deep=3
                 {'RMOD-1/SBTS_RFM_Energy_Monitoring/M40003C0': {'1758635340': 52813},
                  'RMOD-2/SBTS_RFM_Energy_Monitoring/M40003C0': {'1758635340': 62813}}
        :rtype: dict
        """
        def cut_key_path(path, deep=path_deep):
            parts = path.split("/")
            return '/'.join(parts[-deep:]) if len(parts) > deep else path

        wrapped = {}
        for key, values in counters.items():
            new_key = f"{parent_key}/{key}" if parent_key else key
            if re.fullmatch(r"M\d+\w*", key):
                wrapped[cut_key_path(new_key)] = values
                continue
            if isinstance(values, dict):
                wrapped.update(self._wrap_counters(values, new_key, path_deep))

        return wrapped
